type Github = { token: string }

export async function main(gh_auth: Github, repo: string) {
  const res = await fetch(`https://api.github.com/repos/${repo}/issues?state=open`, {
    headers: { Authorization: `Bearer ${gh_auth.token}` }
  })
  const issues = await res.json()
  return { repo, open_issues: issues.length }
}
